def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residual = bins - item
    return np.where(residual >= 0, -residual, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residual = bins - item
    return np.where(residual >= 0, -np.abs(residual - np.sqrt(bins)), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residual = bins - item
    return np.where(residual >= 0, -np.abs(residual - item / 3), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    residual = bins - item
